# ==============================================================================
# Public Macaque TB Granuloma - Spatial Feature Mapping
# ==============================================================================
#
# Purpose:
#   Map representative genes and cross-species conserved granuloma-associated
#   programs onto public macaque lung Mycobacterium tuberculosis granuloma
#   spatial transcriptomics data.
#
# Required input:
#   sample_data_trans:
#     A processed Seurat spatial object generated by:
#       08_Public_Macaque_TB_Lung_Granuloma_ST_Analysis.R
#
# Main outputs generated in memory:
#   spatial_feature_plots
#
# Notes:
#   This script does not save figures to disk.
#   Users can export plots as needed.
# ==============================================================================


# ==============================================================================
# --- 0. Load R packages ---
# ==============================================================================

suppressMessages({
  library(Seurat)
  library(ggplot2)
  library(dplyr)
  library(tidyr)
  library(scales)
  library(viridis)
  library(scico)
})

options(future.globals.maxSize = 9e10)
options(Seurat.object.assay.version = "v5")


# ==============================================================================
# --- 1. Example input object loading ---
# ==============================================================================

project_dir <- "path/to/project"

macaque_tb_object_path <- file.path(
  project_dir,
  "processed_objects",
  "public_macaque_TB_granuloma_processed.rds"
)

if (!exists("sample_data_trans")) {
  sample_data_trans <- readRDS(macaque_tb_object_path)
}

DefaultAssay(sample_data_trans) <- "SCT"

message("Input object:")
print(sample_data_trans)


