# ==============================================================================
# --- 3. Helper functions ---
# ==============================================================================

filter_genes_present <- function(genes, object) {
  
  genes_present <- genes[genes %in% rownames(object)]
  genes_missing <- setdiff(genes, genes_present)
  
  if (length(genes_missing) > 0) {
    warning(
      "The following genes were not found and will be skipped: ",
      paste(genes_missing, collapse = ", ")
    )
  }
  
  return(genes_present)
}


make_spatial_feature_plots <- function(
    object,
    genes,
    program_name,
    image_alpha = 0,
    point_size_factor = 2,
    crop = FALSE,
    palette = c("scico_oslo", "viridis_plasma", "viridis_magma",
                "viridis_mako", "viridis_rocket"),
    lower_limit = 0.5,
    upper_limit = NA_real_
) {
  
  palette <- match.arg(palette)
  
  genes_present <- filter_genes_present(
    genes = genes,
    object = object
  )
  
  if (length(genes_present) == 0) {
    warning("No valid genes for program: ", program_name)
    return(NULL)
  }
  
  plot_list <- list()
  
  for (gene in genes_present) {
    
    p <- SpatialFeaturePlot(
      object = object,
      features = gene,
      pt.size.factor = point_size_factor,
      image.alpha = image_alpha,
      crop = crop
    )
    
    if (palette == "scico_oslo") {
      p <- p +
        scale_fill_scico(
          palette = "oslo",
          direction = -1,
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_plasma") {
      p <- p +
        scale_fill_viridis(
          option = "plasma",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_magma") {
      p <- p +
        scale_fill_viridis(
          option = "magma",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_mako") {
      p <- p +
        scale_fill_viridis(
          option = "mako",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    if (palette == "viridis_rocket") {
      p <- p +
        scale_fill_viridis(
          option = "rocket",
          limits = c(lower_limit, upper_limit),
          oob = scales::squish
        )
    }
    
    p <- p +
      ggtitle(paste0(program_name, " - ", gene))
    
    plot_list[[gene]] <- p
  }
  
  return(plot_list)
}


# ==============================================================================
# --- 4. Select programs for spatial mapping ---
# ==============================================================================

# By default, this script maps selected upstream regulators.
# Users can replace this with any program name from macaque_tb_gene_programs.
selected_programs <- c(
  "Selected upstream regulators"
)

# To map all programs, use:
# selected_programs <- names(macaque_tb_gene_programs)

selected_programs <- intersect(
  selected_programs,
  names(macaque_tb_gene_programs)
)

if (length(selected_programs) == 0) {
  stop("No selected programs were found in macaque_tb_gene_programs.")
}


# ==============================================================================
# --- 5. Generate spatial feature plots ---
# ==============================================================================

spatial_feature_plots <- list()

for (program_name in selected_programs) {
  
  message("Generating spatial feature plots for: ", program_name)
  
  spatial_feature_plots[[program_name]] <- make_spatial_feature_plots(
    object = sample_data_trans,
    genes = macaque_tb_gene_programs[[program_name]],
    program_name = program_name,
    image_alpha = 0,
    point_size_factor = 2,
    crop = FALSE,
    palette = "scico_oslo",
    lower_limit = 0.5,
    upper_limit = NA_real_
  )
}


# Example: print generated plots.
for (program_name in names(spatial_feature_plots)) {
  
  if (!is.null(spatial_feature_plots[[program_name]])) {
    
    for (gene in names(spatial_feature_plots[[program_name]])) {
      print(spatial_feature_plots[[program_name]][[gene]])
    }
  }
}


# ==============================================================================
# --- 6. Example single-gene spatial mapping ---
# ==============================================================================

# Example used in exploratory analysis: MMP9 spatial expression.
single_gene <- "MMP9"

if (single_gene %in% rownames(sample_data_trans)) {
  
  p_single_gene <- SpatialFeaturePlot(
    object = sample_data_trans,
    features = single_gene,
    pt.size.factor = 0,
    image.alpha = 1,
    crop = FALSE
  ) +
    scale_fill_viridis(
      option = "plasma",
      limits = c(0, NA),
      oob = scales::squish
    ) +
    ggtitle(paste0("Macaque TB granuloma - ", single_gene))
  
  print(p_single_gene)
  
} else {
  warning("Gene not found: ", single_gene)
}


